const CAJAS_POR_PALLET = 48;

/**
 * Devuelve cuántos pallets (completos o a medias) hacen falta.
 * Contrato: `cajas` es un entero >= 0; si no, lanza RangeError.
 * Un pallet a medias cuenta como uno entero, porque ocupa el mismo lugar en el camión.
 */
function palletsNecesarios(cajas) {
  if (!Number.isInteger(cajas) || cajas < 0) {
    throw new RangeError(`cajas debe ser un entero >= 0, llegó: ${cajas}`);
  }
  return Math.ceil(cajas / CAJAS_POR_PALLET);
}

