import { readFileSync, existsSync } from "node:fs";
import { execSync } from "node:child_process";

const texto = readFileSync("README.md", "utf8");
let errores = 0;

for (const [, destino] of texto.matchAll(/\]\((?!https?:)([^)#]+)\)/g)) {
  if (!existsSync(destino)) { console.error(`Enlace roto: ${destino}`); errores++; }
}

const bloque = texto.match(/```text\n\$ (.+)\n([\s\S]*?)```/);
if (bloque) {
  const [, comando, esperado] = bloque;
  const real = execSync(comando, { encoding: "utf8" });
  if (real.trim() !== esperado.trim()) {
    console.error(`El ejemplo del README ya no coincide con: ${comando}`); errores++;
  }
}
console.log(errores === 0 ? "docs OK" : `${errores} problema(s)`);
process.exit(errores === 0 ? 0 : 1);
